"use client";

import { useState, useEffect, useMemo } from 'react';
import { Calendar } from '@/components/ui/calendar';
import { getMonthlyAttendance } from '@/app/actions';
import { format } from 'date-fns';
import { ja } from 'date-fns/locale';
import { ChevronLeft, ChevronRight, Clock, LogIn, LogOut } from 'lucide-react';
import { Button } from '@/components/ui/button';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { createSupabaseBrowserClient } from '@/lib/supabase/client';
import { toZonedTime } from 'date-fns-tz';
import { formatJst } from '@/lib/utils';

interface AttendanceRecord {
  date: string;
  status: 'in' | 'out' | 'mixed';
}

interface AttendanceDetails {
  firstIn: string | null;
  lastOut: string | null;
  totalMinutes: number;
}

export default function AttendanceCalendar({ userId }: { userId: string }) {
  const [date, setDate] = useState<Date>(new Date());
  const [selectedDate, setSelectedDate] = useState<Date | undefined>(new Date());
  const [attendance, setAttendance] = useState<AttendanceRecord[]>([]);
  const [attendanceDetails, setAttendanceDetails] = useState<AttendanceDetails | null>(null);
  const [isLoading, setIsLoading] = useState(true);

  useEffect(() => {
    const fetchAttendance = async () => {
      setIsLoading(true);
      const data = await getMonthlyAttendance(userId, date);
      setAttendance(data);
      setIsLoading(false);
    };
    fetchAttendance();
  }, [userId, date]);

  useEffect(() => {
    const fetchDayDetails = async () => {
      if (!selectedDate) {
        setAttendanceDetails(null);
        return;
      }

      const supabase = createSupabaseBrowserClient();
      const dateStr = format(selectedDate, 'yyyy-MM-dd');

      const { data: records, error } = await supabase
        .schema('attendance')
        .from('attendances')
        .select('type, timestamp')
        .eq('user_id', userId)
        .eq('date', dateStr)
        .order('timestamp');

      if (error || !records || records.length === 0) {
        setAttendanceDetails(null);
        return;
      }

      const inRecords = records.filter(r => r.type === 'in');
      const outRecords = records.filter(r => r.type === 'out');

      const firstIn = inRecords.length > 0 ? inRecords[0].timestamp : null;
      const lastOut = outRecords.length > 0 ? outRecords[outRecords.length - 1].timestamp : null;

      let totalMinutes = 0;
      let lastInTime: Date | null = null;

      records.forEach(rec => {
        if (rec.type === 'in') {
          lastInTime = new Date(rec.timestamp);
        } else if (rec.type === 'out' && lastInTime) {
          const outTime = new Date(rec.timestamp);
          totalMinutes += (outTime.getTime() - lastInTime.getTime()) / (1000 * 60);
          lastInTime = null;
        }
      });

      if (lastInTime) {
        totalMinutes += (new Date().getTime() - lastInTime.getTime()) / (1000 * 60);
      }

      setAttendanceDetails({
        firstIn,
        lastOut,
        totalMinutes: Math.round(totalMinutes),
      });
    };

    fetchDayDetails();
  }, [userId, selectedDate]);

  const handleMonthChange = (month: Date) => {
    setDate(month);
    if (selectedDate) {
      const newSelectedDate = new Date(month.getFullYear(), month.getMonth(), selectedDate.getDate());
      setSelectedDate(newSelectedDate);
    }
  };

  const goToPreviousMonth = () => {
    handleMonthChange(new Date(date.getFullYear(), date.getMonth() - 1, 1));
  }

  const goToNextMonth = () => {
    handleMonthChange(new Date(date.getFullYear(), date.getMonth() + 1, 1));
  }

  const attendedDays = useMemo(() => attendance.map(a => new Date(a.date.replace(/-/g, '/'))), [attendance]);

  const handleDayClick = (day: Date | undefined) => {
    setSelectedDate(day);
  };

  const formatTime = (timestamp: string | null) => {
    if (!timestamp) return '-';
    return formatJst(new Date(timestamp), 'HH:mm');
  };

  const formatDuration = (minutes: number) => {
    if (isNaN(minutes) || minutes < 0) return '0時間0分';
    const hours = Math.floor(minutes / 60);
    const mins = minutes % 60;
    return `${hours}時間${mins}分`;
  };

  return (
    <div className="grid grid-cols-1 lg:grid-cols-2 gap-4">
      <div>
        <div className="flex justify-between items-center mb-2 px-1">
            <h3 className="text-lg font-semibold">
                {formatJst(date, 'yyyy年 M月')}
            </h3>
            <div className='flex items-center gap-1'>
              <Button variant="ghost" size="icon" onClick={goToPreviousMonth} disabled={isLoading}>
                  <ChevronLeft />
              </Button>
              <Button variant="ghost" size="icon" onClick={goToNextMonth} disabled={isLoading}>
                  <ChevronRight />
              </Button>
            </div>
        </div>
      <Calendar
        month={date}
        onMonthChange={handleMonthChange}
        onDayClick={handleDayClick}
        disabled={isLoading}
        className="rounded-md border"
        showOutsideDays
        locale={ja}
        components={{
          Caption: () => null,
        }}
        modifiers={{
          attended: attendedDays,
          selected: selectedDate ? [selectedDate] : []
        }}
        modifiersClassNames={{
          attended: 'is-attended'
        }}
      />
       <div className="mt-4 space-y-2 text-sm">
            <div className="flex items-center gap-2"><div className="w-4 h-4 rounded-full bg-primary/20 border border-primary"></div>出勤日</div>
        </div>
      </div>

      <div>
        {selectedDate && (
          <Card>
            <CardHeader>
              <CardTitle className="text-lg">
                {format(selectedDate, 'M月d日(E)', { locale: ja })} の詳細
              </CardTitle>
            </CardHeader>
            <CardContent>
              {attendanceDetails ? (
                <div className="space-y-4">
                  <div className="flex items-center gap-3">
                    <LogIn className="h-5 w-5 text-green-600" />
                    <div>
                      <div className="text-sm text-muted-foreground">初回出勤</div>
                      <div className="text-lg font-semibold">{formatTime(attendanceDetails.firstIn)}</div>
                    </div>
                  </div>
                  <div className="flex items-center gap-3">
                    <LogOut className="h-5 w-5 text-red-600" />
                    <div>
                      <div className="text-sm text-muted-foreground">最終退勤</div>
                      <div className="text-lg font-semibold">{formatTime(attendanceDetails.lastOut)}</div>
                    </div>
                  </div>
                  <div className="flex items-center gap-3">
                    <Clock className="h-5 w-5 text-blue-600" />
                    <div>
                      <div className="text-sm text-muted-foreground">活動時間</div>
                      <div className="text-lg font-semibold">{formatDuration(attendanceDetails.totalMinutes)}</div>
                    </div>
                  </div>
                </div>
              ) : (
                <div className="text-center py-8 text-muted-foreground">
                  この日の出勤記録はありません
                </div>
              )}
            </CardContent>
          </Card>
        )}
      </div>
    </div>
  );
}

import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { createSupabaseServerClient } from "@/lib/supabase/server";
import { BarChart, Calendar as CalendarIcon, Clock, Percent } from "lucide-react";
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "@/components/ui/table"
import { Badge } from "@/components/ui/badge";
import { subDays } from "date-fns";
import AttendanceCalendar from "./components/AttendanceCalendar";
import ClientRelativeTime from "./components/ClientRelativeTime";
import CardMigrationAlert from "./components/CardMigrationAlert";
import { calculateTotalActivityTime } from "../actions";
import { convertGenerationToGrade, formatJst } from "@/lib/utils";
import { redirect } from "next/navigation";
import { toZonedTime } from "date-fns-tz";

export const dynamic = 'force-dynamic';

const timeZone = 'Asia/Tokyo';

export default async function DashboardPage() {
    const supabase = await createSupabaseServerClient();
    const { data: { user } } = await supabase.auth.getUser();

    if (!user) {
        redirect('/login');
    }

    // プロフィールと勤怠ユーザーを並列取得
    const [profileResult, attendanceUserResult] = await Promise.all([
      supabase
        .schema('member')
        .from('members')
        .select(`
            discord_uid,
            generation,
            is_admin,
            joined_at,
            display_name,
            member_team_relations(teams(name))
        `)
        .eq('supabase_auth_user_id', user!.id)
        .single(),
      supabase
        .schema('attendance')
        .from('users')
        .select('card_id')
        .eq('supabase_auth_user_id', user!.id)
        .single(),
    ]);

    const { data: profile, error: profileError } = profileResult;

    if (profileError || !profile) {
        console.error('Profile fetch error:', profileError);
        redirect('/register/member-unregistered');
    }

    const hasCardId = attendanceUserResult.data?.card_id && attendanceUserResult.data.card_id.trim() !== '';

    // display_nameがDBにあればそれを使用（Discord API不要）
    const displayName = profile.display_name || '名無しさん';
    let firstname = '';
    let lastname = '';
    if (displayName !== '名無しさん') {
        const nameParts = displayName.split(/\s+/);
        if (nameParts.length >= 2) {
            lastname = nameParts[0].toLowerCase();
            firstname = nameParts[1].toLowerCase();
        }
    }

    const today = toZonedTime(new Date(), timeZone);
    const thirtyDaysAgo = formatJst(subDays(today, 30), 'yyyy-MM-dd');
    const userCreatedAtDate = formatJst(new Date(profile!.joined_at), 'yyyy-MM-dd');

    // 出勤データの取得を全て並列化
    const [attendancesResult, totalActivityTimeInHours, distinctDatesResult, totalClubActivityDatesResult] = await Promise.all([
      supabase.schema('attendance').from('attendances').select('*').eq('user_id', user!.id).order('timestamp', { ascending: false }).limit(5),
      calculateTotalActivityTime(user!.id, 30),
      supabase
        .schema('attendance')
        .from('attendances')
        .select('date')
        .eq('user_id', user!.id)
        .eq('type', 'in')
        .gte('date', thirtyDaysAgo),
      supabase
        .schema('attendance')
        .from('attendances')
        .select('date')
        .eq('type', 'in')
        .gte('date', thirtyDaysAgo)
        .gte('date', userCreatedAtDate),
    ]);

    const { data: attendances } = attendancesResult;
    const { data: distinctDates } = distinctDatesResult;
    const { data: totalClubActivityDates } = totalClubActivityDatesResult;

    const userAttendanceDays = distinctDates ? new Set(distinctDates.map(d => d.date)).size : 0;
    const totalClubDays = totalClubActivityDates ? new Set(totalClubActivityDates.map(d => d.date)).size : 0;

    const attendanceRate = totalClubDays > 0 ? (userAttendanceDays / totalClubDays) * 100 : 0;

    const teamName = profile?.member_team_relations?.[0]?.teams?.name;

  return (
    <div className="space-y-6">
        {!hasCardId && (
            <CardMigrationAlert
                userId={user!.id}
                firstname={firstname}
                lastname={lastname}
            />
        )}

        <div className="flex justify-between items-start">
            <div>
                <h1 className="text-3xl font-bold">マイダッシュボード</h1>
                <p className="text-muted-foreground">こんにちは, {displayName}さん！</p>
            </div>
            <div className="text-right">
                {teamName && <Badge variant="secondary">{teamName}</Badge>}
                <p className="text-sm text-muted-foreground">{profile?.generation ? convertGenerationToGrade(profile.generation) : ''}</p>
            </div>
        </div>

        <div className="grid gap-4 grid-cols-1 sm:grid-cols-2 lg:grid-cols-4">
            <Card>
                <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
                    <CardTitle className="text-sm font-medium">出勤日数</CardTitle>
                    <CalendarIcon className="h-4 w-4 text-muted-foreground" />
                </CardHeader>
                <CardContent>
                    <div className="text-2xl font-bold">{userAttendanceDays}日</div>
                     <p className="text-xs text-muted-foreground">
                        過去30日間
                    </p>
                </CardContent>
            </Card>
            <Card>
                <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
                    <CardTitle className="text-sm font-medium">活動時間 (概算)</CardTitle>
                    <Clock className="h-4 w-4 text-muted-foreground" />
                </CardHeader>
                <CardContent>
                    <div className="text-2xl font-bold">{totalActivityTimeInHours.toFixed(1)} 時間</div>
                    <p className="text-xs text-muted-foreground">
                        過去30日間
                    </p>
                </CardContent>
            </Card>
            <Card>
                <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
                    <CardTitle className="text-sm font-medium">出勤率</CardTitle>
                    <Percent className="h-4 w-4 text-muted-foreground" />
                </CardHeader>
                <CardContent>
                    <div className="text-2xl font-bold">{attendanceRate.toFixed(1)}%</div>
                    <p className="text-xs text-muted-foreground">
                        活動日数(登録後): {totalClubDays}日
                    </p>
                </CardContent>
            </Card>
            <Card>
                <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
                    <CardTitle className="text-sm font-medium">直近の活動</CardTitle>
                    <BarChart className="h-4 w-4 text-muted-foreground" />
                </CardHeader>
                <CardContent>
                    <div className="text-2xl font-bold">{attendances && attendances.length > 0 ? (attendances[0].type === 'in' ? '活動中' : '退勤済み') : '記録なし'}</div>
                </CardContent>
            </Card>
      </div>
      <div className="grid gap-6">
        <div className="grid gap-6">
            <Card>
                <CardHeader>
                    <CardTitle>最近の出退勤記録</CardTitle>
                </CardHeader>
                <CardContent>
                    <Table>
                        <TableHeader>
                            <TableRow>
                            <TableHead>種別</TableHead>
                            <TableHead>日時</TableHead>
                            <TableHead>相対時間</TableHead>
                            </TableRow>
                        </TableHeader>
                        <TableBody>
                            {attendances && attendances.length > 0 ? attendances.map((att) => (
                                <TableRow key={att.id}>
                                    <TableCell>
                                        <Badge variant={att.type === 'in' ? 'default' : 'secondary'}>
                                            {att.type === 'in' ? '出勤' : '退勤'}
                                        </Badge>
                                    </TableCell>
                                    <TableCell>{formatJst(new Date(att.timestamp), 'yyyy/MM/dd HH:mm:ss')}</TableCell>
                                    <TableCell><ClientRelativeTime date={att.timestamp} /></TableCell>
                                </TableRow>
                            )) : (
                                <TableRow>
                                    <TableCell colSpan={3} className="text-center">記録がありません。</TableCell>
                                </TableRow>
                            )}
                        </TableBody>
                    </Table>
                </CardContent>
            </Card>
             <Card>
                <CardHeader>
                <CardTitle>出勤カレンダー</CardTitle>
                </CardHeader>
                <CardContent>
                    <AttendanceCalendar userId={user!.id} />
                </CardContent>
            </Card>
        </div>
      </div>
    </div>
  );
}

